/* ==========================================================================
   fortuneCougar - dark casino theme (layered on bslib / Bootstrap 5)
   ========================================================================== */
:root {
  --fc-bg: #0b0418;
  --fc-panel: rgba(31, 12, 58, .78);
  --fc-panel-2: rgba(46, 18, 84, .85);
  --fc-line: rgba(255, 255, 255, .08);
  --fc-gold: #ffcc00;
  --fc-gold-2: #ff9f1c;
  --fc-pink: #ff2e88;
  --fc-purple: #7b2cbf;
  --fc-cyan: #00c2ff;
  --fc-green: #1fd18b;
  --fc-red: #ff4d6d;
  --fc-text: #f3eaff;
  --fc-muted: #b9a6d9;
  --gold-grad: linear-gradient(180deg, #fff3a8 0%, #ffd23f 40%, #ff9f1c 100%);
  --pink-grad: linear-gradient(135deg, #ff2e88 0%, #ff7a45 100%);
  --display: 'Bungee', 'Poppins', 'Segoe UI', system-ui, sans-serif;
}

html, body { background: var(--fc-bg); }
body { color: var(--fc-text); background: var(--fc-bg) !important; min-height: 100vh; }
/* fixed, composited background layers (no repaint on scroll) */
body::after {
  content: ""; position: fixed; inset: 0; pointer-events: none; z-index: -1;
  background:
    radial-gradient(1200px 600px at 10% -10%, rgba(123, 44, 191, .45), transparent 60%),
    radial-gradient(900px 500px at 110% 10%, rgba(255, 46, 136, .25), transparent 60%),
    radial-gradient(800px 600px at 50% 120%, rgba(0, 194, 255, .12), transparent 60%);
}
body::before {
  content: ""; position: fixed; inset: 0; pointer-events: none; z-index: 0; opacity: .35;
  background-image: radial-gradient(rgba(255,255,255,.55) 1px, transparent 1.4px);
  background-size: 46px 46px;
  mask-image: linear-gradient(180deg, #000 0%, transparent 70%);
}
/* the navbar (and its dropdown menus) must stack above the page content */
.container-fluid { position: relative; z-index: 1; }
.navbar { position: relative; z-index: 1030; }
h1, h2, h3, h4 { font-family: var(--display); letter-spacing: .5px; }

/* ---------------------------------------------------------------- navbar */
.navbar {
  background: linear-gradient(90deg, #1a0536 0%, #3a0b5e 45%, #5c0c5f 100%) !important;
  border-bottom: 2px solid rgba(255, 204, 0, .45);
  box-shadow: 0 6px 30px rgba(0, 0, 0, .55);
  padding: .35rem 1rem;
}
/* page_navbar() emits BS3-style markup (li > a, li.active) that bslib's
   compatibility layer upgrades at run time: style both forms */
.navbar .nav-link, .navbar .navbar-nav > li > a {
  color: #e9dcff !important; font-weight: 600; font-size: .8rem; text-transform: uppercase; letter-spacing: .3px;
  border-radius: .6rem; padding: .4rem .55rem !important; white-space: nowrap; text-decoration: none; display: block;
}
.navbar .nav-link:hover, .navbar .navbar-nav > li > a:hover { background: rgba(255,255,255,.08); color: #fff !important; }
.navbar .nav-link.active, .navbar .nav-item.show > .nav-link,
.navbar .navbar-nav > li.active > a, .navbar .navbar-nav > li > a.active, .navbar .navbar-nav > li.show > a {
  color: #1a0933 !important; background: var(--gold-grad) !important; box-shadow: 0 0 18px rgba(255, 204, 0, .45);
}
.navbar .dropdown-menu { background: #1d0838; border: 1px solid rgba(255, 204, 0, .35); border-radius: .8rem; box-shadow: 0 18px 40px rgba(0,0,0,.6); padding: .35rem; }
.navbar .dropdown-item, .navbar .dropdown-menu > li > a {
  display: block; padding: .45rem .8rem; color: #eadcff; font-weight: 600; border-radius: .5rem; text-decoration: none; white-space: nowrap;
}
.navbar .dropdown-item:hover, .navbar .dropdown-item.active,
.navbar .dropdown-menu > li > a:hover, .navbar .dropdown-menu > li.active > a, .navbar .dropdown-menu > li > a.active {
  background: var(--pink-grad); color: #fff;
}
.brand { display: inline-flex; align-items: center; gap: .45rem; }
.brand-logo { font-size: 1.7rem; filter: drop-shadow(0 0 10px rgba(255, 46, 136, .8)); }
.brand-text { font-family: var(--display); font-size: 1.25rem; color: #fff; }
.brand-text b { background: var(--gold-grad); -webkit-background-clip: text; background-clip: text; color: transparent; font-weight: 400; }
.navbar-nav { align-items: center; gap: .15rem; }

/* HUD */
.hud { display: flex; align-items: center; gap: .35rem; flex-wrap: nowrap; }
.hud > * { background: rgba(10, 2, 24, .55); border: 1px solid rgba(255,255,255,.12); border-radius: 999px; padding: .22rem .6rem; font-weight: 700; font-size: .84rem; white-space: nowrap; }
.hud-avatar { font-size: 1.35rem; padding: .05rem .45rem !important; cursor: pointer; color: inherit; }
.hud-avatar:hover { border-color: var(--fc-gold); }
.hud-level { display: flex; align-items: center; gap: .45rem; }
.hud-lv { color: var(--fc-cyan); font-size: .78rem; }
.hud-xp { width: 56px; height: 8px; background: rgba(255,255,255,.12); border-radius: 9px; overflow: hidden; }
.hud-xp-fill { height: 100%; width: 0; background: linear-gradient(90deg, var(--fc-cyan), #7df9ff); transition: width .6s ease; }
.hud-coins { font-size: .98rem !important; border-color: rgba(255, 204, 0, .55) !important; min-width: 128px; text-align: right; }
.hud-coins #hud-coins { background: var(--gold-grad); -webkit-background-clip: text; background-clip: text; color: transparent; font-variant-numeric: tabular-nums; }
.hud-coins.gain { animation: coinGain .9s ease; }
@keyframes coinGain { 0% { box-shadow: 0 0 0 rgba(255,204,0,0); } 40% { box-shadow: 0 0 26px rgba(255,204,0,.85); transform: scale(1.06); } 100% { box-shadow: 0 0 0 rgba(255,204,0,0); } }
.hud-coin-icon { margin-right: .3rem; }
.hud-vip { border-width: 2px !important; font-size: .78rem !important; }
.hud-turbo { cursor: pointer; color: #8a7aa8; }
.hud-lang { cursor: pointer; color: #f3eaff; font-size: .78rem !important; }
.hud-lang:hover, .hud-turbo:hover { border-color: var(--fc-gold) !important; }
.hud-turbo.on { color: #1a0933; background: var(--gold-grad) !important; box-shadow: 0 0 14px rgba(255,204,0,.6); }

/* ----------------------------------------------------------- common UI */
.page-header { display: flex; align-items: center; justify-content: space-between; gap: 1rem; flex-wrap: wrap; margin: 1.1rem 0 1rem; }
.ph-left { display: flex; align-items: center; gap: .9rem; }
.ph-icon { font-size: 2.6rem; filter: drop-shadow(0 0 14px rgba(255, 204, 0, .45)); }
.page-header h2 { margin: 0; font-size: 1.7rem; background: var(--gold-grad); -webkit-background-clip: text; background-clip: text; color: transparent; }
.page-header p { margin: .15rem 0 0; color: var(--fc-muted); font-size: .92rem; }
.ph-count { color: var(--fc-muted); font-weight: 700; }
.ctl-label { font-size: .68rem; letter-spacing: 1.5px; color: var(--fc-muted); font-weight: 800; text-transform: uppercase; }
.rules-line { color: var(--fc-muted); font-size: .85rem; margin: .2rem 0 .8rem; }

.btn-deal, .btn-act, .btn-claim, .btn-buy, .btn-collect, .btn-bonus-action, .btn-call, .btn-clear, .btn-back {
  border: none; border-radius: 999px; font-weight: 800; letter-spacing: .6px; cursor: pointer; transition: transform .12s ease, box-shadow .2s ease, filter .2s;
}
.btn-deal, .btn-collect, .btn-bonus-action {
  background: var(--pink-grad); color: #fff; padding: .7rem 1.8rem; font-size: 1.05rem;
  box-shadow: 0 6px 0 #8a1048, 0 10px 30px rgba(255, 46, 136, .45);
}
.btn-deal:hover, .btn-collect:hover, .btn-bonus-action:hover { filter: brightness(1.1); transform: translateY(-1px); color: #fff; }
.btn-deal:active, .btn-collect:active { transform: translateY(3px); box-shadow: 0 2px 0 #8a1048; }
.btn-deal.gold, .btn-act.gold { background: var(--gold-grad); color: #2a1300; box-shadow: 0 5px 0 #a35f00, 0 8px 24px rgba(255, 204, 0, .35); }
.btn-act { background: linear-gradient(180deg, #5b2a9c, #3b1670); color: #fff; padding: .55rem 1.2rem; box-shadow: 0 4px 0 #220a45; }
.btn-act:hover { filter: brightness(1.15); color: #fff; }
.btn-act.red { background: linear-gradient(180deg, #ff4d6d, #c9184a); box-shadow: 0 4px 0 #7a0c2c; }
.btn-act.disabled, .btn-act:disabled, .btn-buy.disabled, .btn-buy:disabled { opacity: .38; cursor: not-allowed; filter: grayscale(.6); }
.btn-claim { position: relative; background: linear-gradient(180deg, #2df5a3, #10a36a); color: #042b1b; padding: .35rem 1rem; font-size: .8rem; box-shadow: 0 3px 0 #06613e; }
.btn-clear, .btn-back { background: rgba(255,255,255,.08); color: #e9dcff; padding: .35rem .9rem; font-size: .78rem; border: 1px solid rgba(255,255,255,.15); }
.btn-back:hover, .btn-clear:hover { background: rgba(255,255,255,.16); }
/* glow pulse = opacity animation on a pseudo-element (compositor only) */
.pulse, .btn-claim { position: relative; }
.pulse::after, .btn-claim::after {
  content: ""; position: absolute; inset: -3px; border-radius: inherit; pointer-events: none;
  box-shadow: 0 0 22px 4px rgba(255, 204, 0, .6); opacity: 0; animation: glowPulse 1.6s ease-in-out infinite; will-change: opacity;
}
@keyframes glowPulse { 50% { opacity: 1; } }
.claimed-tag { color: var(--fc-green); font-weight: 800; font-size: .8rem; }
.lock-tag, .reward-tag { color: var(--fc-muted); font-size: .8rem; font-weight: 700; }

.fc-progress { position: relative; height: 16px; border-radius: 99px; background: rgba(255,255,255,.1); overflow: hidden; }
.fc-progress-fill { height: 100%; background: linear-gradient(90deg, var(--fc-pink), var(--fc-gold)); border-radius: 99px; transition: width .6s ease; box-shadow: 0 0 12px rgba(255, 46, 136, .6); }
.fc-progress-label { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-size: .68rem; font-weight: 800; color: #fff; text-shadow: 0 1px 2px #000; }

/* variant pills (radioButtons restyled) */
.variant-pills .shiny-input-container { width: 100% !important; margin: 0; }
.variant-pills .shiny-options-group { display: flex; flex-wrap: wrap; gap: .5rem; }
.variant-pills .form-check-inline, .multi-ctl .form-check-inline { margin: 0; padding: 0; }
.variant-pills .form-check-input, .multi-ctl .form-check-input { display: none; }
.variant-pills .form-check-label, .multi-ctl .form-check-label {
  display: inline-block; padding: .5rem 1.1rem; border-radius: 999px; cursor: pointer; font-weight: 700; font-size: .9rem;
  background: rgba(255,255,255,.06); border: 1px solid rgba(255,255,255,.14); color: #dccbff; transition: all .15s;
}
.variant-pills .form-check-label:hover { border-color: var(--fc-gold); color: #fff; }
.variant-pills .form-check-input:checked + .form-check-label,
.variant-pills input:checked + span, .multi-ctl input:checked + span, .multi-ctl .form-check-input:checked + .form-check-label {
  background: var(--gold-grad); color: #2a1300; border-color: transparent; box-shadow: 0 0 18px rgba(255, 204, 0, .45);
}
.variant-pills label > span, .multi-ctl label > span { display: inline-block; padding: .5rem 1.1rem; border-radius: 999px; cursor: pointer; font-weight: 700; background: rgba(255,255,255,.06); border: 1px solid rgba(255,255,255,.14); }
.variant-pills .radio-inline input, .multi-ctl .radio-inline input { display: none; }

/* ---------------------------------------------------------------- lobby */
.lobby { padding-bottom: 3rem; }
.hero {
  margin-top: 1.2rem; border-radius: 1.6rem; padding: 2.2rem 2.4rem; display: flex; justify-content: space-between; align-items: center; gap: 1rem; overflow: hidden; position: relative;
  background: radial-gradient(600px 300px at 85% 40%, rgba(255, 204, 0, .28), transparent 60%), linear-gradient(120deg, #3a0b6b 0%, #7b1b8f 55%, #c2185b 100%);
  border: 2px solid rgba(255, 204, 0, .45); box-shadow: 0 20px 60px rgba(0,0,0,.5), inset 0 0 80px rgba(255,255,255,.05);
}
.hero-kicker { font-weight: 800; letter-spacing: 4px; color: #ffd6ec; font-size: .8rem; }
.hero-title { font-size: clamp(2.2rem, 5vw, 3.8rem); margin: .2rem 0; color: #fff; text-shadow: 0 4px 0 rgba(0,0,0,.35); }
.hero-title span { background: var(--gold-grad); -webkit-background-clip: text; background-clip: text; color: transparent; }
.hero-sub { color: #f6e6ff; max-width: 560px; }
.hero-ctas { display: flex; gap: .7rem; flex-wrap: wrap; margin-top: 1rem; }
.hero-art { display: grid; grid-template-columns: repeat(2, 1fr); gap: .4rem; font-size: clamp(2.5rem, 6vw, 4.6rem); }
.hero-art span { display: inline-block; animation: floaty 3.2s ease-in-out infinite; will-change: transform; filter: drop-shadow(0 10px 14px rgba(0,0,0,.45)); }
.hero-art span:nth-child(2) { animation-delay: .4s; } .hero-art span:nth-child(3) { animation-delay: .8s; } .hero-art span:nth-child(4) { animation-delay: 1.2s; }
@keyframes floaty { 0%,100% { transform: translateY(0) rotate(-3deg); } 50% { transform: translateY(-10px) rotate(3deg); } }

.jackpot-banner { margin: 1.2rem 0; padding: 1rem 1.3rem; border-radius: 1.2rem; cursor: pointer; background: linear-gradient(90deg, #1b0a00, #3d2200 50%, #1b0a00); border: 2px solid #d4af37; box-shadow: 0 0 30px rgba(212, 175, 55, .25); }
.jb-title { font-family: var(--display); color: #ffd23f; font-size: .95rem; margin-bottom: .6rem; }
.jb-title span { font-family: 'Poppins', sans-serif; color: #c9a96b; font-size: .72rem; margin-left: .5rem; }
.jb-pots { display: grid; grid-template-columns: repeat(4, 1fr); gap: .7rem; }
.jb-pot, .jp-pill { border-radius: .8rem; padding: .45rem .7rem; text-align: center; background: rgba(0,0,0,.45); border: 1px solid rgba(255, 204, 0, .35); }
.jb-tier, .jp-label { display: block; font-size: .68rem; font-weight: 800; letter-spacing: 2px; color: #ffe8a3; }
.jb-val, .jp-value { display: block; font-family: var(--display); font-size: 1.15rem; background: var(--gold-grad); -webkit-background-clip: text; background-clip: text; color: transparent; font-variant-numeric: tabular-nums; }
.jb-pot.grand, .jp-grand { border-color: #ff2e88; box-shadow: 0 0 18px rgba(255, 46, 136, .45); }
.jb-pot.major, .jp-major { border-color: #00c2ff; }
.jb-last { margin-top: .5rem; color: #ffd23f; font-size: .8rem; }

.cat-row { display: grid; grid-template-columns: repeat(6, 1fr); gap: .8rem; margin: 1rem 0 1.4rem; }
.cat-card { cursor: pointer; border-radius: 1.1rem; padding: 1rem; text-align: center; border: 1px solid rgba(255,255,255,.12); transition: transform .15s, box-shadow .2s; background: var(--fc-panel); }
.cat-card:hover { transform: translateY(-4px); box-shadow: 0 14px 30px rgba(0,0,0,.45), 0 0 24px rgba(255, 204, 0, .25); border-color: var(--fc-gold); }
.cat-icon { font-size: 2.4rem; }
.cat-title { font-family: var(--display); font-size: .95rem; margin-top: .3rem; }
.cat-sub { color: var(--fc-muted); font-size: .75rem; }
.c-classic { background: linear-gradient(160deg, #5d0f2e, #22061a); } .c-myth { background: linear-gradient(160deg, #5b4100, #1f1200); }
.c-animal { background: linear-gradient(160deg, #0f4d2e, #06190f); } .c-bj { background: linear-gradient(160deg, #0b5d3b, #052418); }
.c-vp { background: linear-gradient(160deg, #0d2f6b, #061330); } .c-rl { background: linear-gradient(160deg, #6b0d1f, #2a0510); }
.lobby-section { margin: 1.6rem 0 .8rem; font-size: 1.2rem; color: #fff; }

/* game tiles */
.tile-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); gap: 1rem; padding-bottom: 2rem; }
.tile-grid.compact { grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); }
.game-tile {
  position: relative; border-radius: 1.2rem; overflow: hidden; cursor: pointer; min-height: 230px; display: flex; flex-direction: column;
  background: linear-gradient(160deg, var(--t1, #3a0b6b), var(--t2, #12041f)); border: 1px solid rgba(255,255,255,.14);
  box-shadow: 0 10px 24px rgba(0,0,0,.4); transition: transform .18s ease, box-shadow .2s ease;
}
.game-tile:hover { transform: translateY(-5px) scale(1.015); box-shadow: 0 18px 40px rgba(0,0,0,.55), 0 0 30px var(--glow, rgba(255,204,0,.3)); border-color: rgba(255, 204, 0, .6); }
.tile-art { font-size: 4.2rem; text-align: center; padding: 1rem 0 .2rem; filter: drop-shadow(0 10px 14px rgba(0,0,0,.5)); transition: transform .3s; }
.game-tile:hover .tile-art { transform: scale(1.12) rotate(-4deg); }
.tile-body { padding: .3rem 1rem 1rem; flex: 1; }
.tile-name { font-family: var(--display); font-size: 1.02rem; color: #fff; }
.tile-tag { font-size: .8rem; color: rgba(255,255,255,.78); min-height: 2.4em; }
.tile-chips { display: flex; flex-wrap: wrap; gap: .3rem; margin-top: .4rem; }
.chip-mini { font-size: .64rem; font-weight: 700; padding: .12rem .5rem; border-radius: 99px; background: rgba(0,0,0,.35); color: #f3e8ff; border: 1px solid rgba(255,255,255,.14); }
.chip-mini.vol { background: rgba(255, 204, 0, .2); color: #ffe27a; border-color: rgba(255, 204, 0, .4); }
.tile-play { position: absolute; top: .7rem; right: .7rem; font-weight: 900; font-size: .7rem; padding: .25rem .7rem; border-radius: 99px; background: var(--gold-grad); color: #2a1300; opacity: 0; transform: translateY(-6px); transition: all .2s; }
.game-tile:hover .tile-play { opacity: 1; transform: none; }

/* machine themes: --t1/--t2 cabinet gradient, --glow accent */
.theme-classic { --t1: #7a1030; --t2: #2a0612; --glow: rgba(255, 80, 80, .45); }
.theme-bank { --t1: #5c4300; --t2: #1b1200; --glow: rgba(255, 204, 0, .5); }
.theme-vegas { --t1: #5b0f7a; --t2: #0f0630; --glow: rgba(255, 46, 200, .55); }
.theme-ruby { --t1: #8a0b2d; --t2: #24020b; --glow: rgba(255, 40, 90, .55); }
.theme-queens { --t1: #6b1a5e; --t2: #1d0619; --glow: rgba(255, 130, 220, .45); }
.theme-rapid { --t1: #7a2a00; --t2: #1d0900; --glow: rgba(255, 140, 0, .55); }
.theme-egypt { --t1: #7a5a12; --t2: #231703; --glow: rgba(255, 210, 90, .5); }
.theme-stone { --t1: #3f4a3a; --t2: #111510; --glow: rgba(150, 230, 140, .45); }
.theme-pirate { --t1: #12456b; --t2: #05131f; --glow: rgba(0, 194, 255, .45); }
.theme-giant { --t1: #2e6b1d; --t2: #0b1d06; --glow: rgba(140, 255, 90, .45); }
.theme-fairy { --t1: #3b4bb0; --t2: #0e1238; --glow: rgba(160, 190, 255, .55); }
.theme-phoenix { --t1: #8a1a00; --t2: #260600; --glow: rgba(255, 110, 0, .6); }
.theme-dragon { --t1: #6b0a0a; --t2: #140303; --glow: rgba(255, 60, 30, .55); }
.theme-ocean { --t1: #005b7a; --t2: #011a24; --glow: rgba(0, 220, 255, .5); }
.theme-west { --t1: #7a4a1a; --t2: #221205; --glow: rgba(255, 170, 80, .5); }
.theme-tiger { --t1: #8a4a00; --t2: #231200; --glow: rgba(255, 150, 0, .55); }
.theme-kitty { --t1: #a0307a; --t2: #2b0a22; --glow: rgba(255, 130, 210, .55); }
.theme-candy { --t1: #c2337a; --t2: #3b0a2a; --glow: rgba(255, 140, 200, .6); }
.theme-franken { --t1: #1f5b3a; --t2: #06160e; --glow: rgba(60, 255, 150, .5); }
.theme-vixen { --t1: #5e0f4a; --t2: #16030f; --glow: rgba(255, 60, 170, .55); }
.theme-jungle { --t1: #0f3b2a; --t2: #03100a; --glow: rgba(80, 255, 170, .45); }
.theme-vampire { --t1: #5a0010; --t2: #130004; --glow: rgba(255, 30, 60, .6); }

/* ------------------------------------------------------------ slot machine */
.machine-nav { display: flex; align-items: center; justify-content: space-between; gap: .6rem; margin: 1rem 0 .6rem; flex-wrap: wrap; }
.machine-switch { display: flex; gap: .3rem; flex-wrap: wrap; }
.ms-pill { border: 1px solid rgba(255,255,255,.15); background: rgba(255,255,255,.05); border-radius: .7rem; font-size: 1.25rem; width: 2.5rem; height: 2.5rem; cursor: pointer; transition: all .15s; color: inherit; }
.ms-pill:hover { transform: translateY(-2px); border-color: var(--fc-gold); }
.ms-pill.active { background: var(--gold-grad); box-shadow: 0 0 14px rgba(255,204,0,.5); }

.slot-machine {
  max-width: 1080px; margin: 0 auto 2.5rem; border-radius: 1.8rem; padding: 1rem 1.2rem 1.1rem; position: relative;
  background: radial-gradient(900px 400px at 50% -10%, rgba(255,255,255,.12), transparent 60%), linear-gradient(170deg, var(--t1), var(--t2));
  border: 3px solid transparent;
  background-clip: padding-box;
  box-shadow: 0 0 0 3px #d4af37, 0 0 0 7px #3b1b00, 0 0 45px var(--glow), 0 30px 60px rgba(0,0,0,.6), inset 0 2px 20px rgba(255,255,255,.12);
}
.sm-top { display: flex; justify-content: space-between; align-items: center; gap: .8rem; flex-wrap: wrap; }
.sm-title { display: flex; align-items: center; gap: .8rem; }
.sm-art { font-size: 2.8rem; filter: drop-shadow(0 0 14px var(--glow)); }
.sm-title h3 { margin: 0; font-size: 1.55rem; background: var(--gold-grad); -webkit-background-clip: text; background-clip: text; color: transparent; filter: drop-shadow(0 2px 0 rgba(0,0,0,.5)); }
.sm-title p { margin: 0; color: rgba(255,255,255,.8); font-size: .85rem; }
.sm-badges { display: flex; align-items: center; gap: .4rem; }
.badge-vol, .badge-rtp { font-size: .7rem; font-weight: 800; padding: .25rem .65rem; border-radius: 99px; background: rgba(0,0,0,.4); border: 1px solid rgba(255,255,255,.2); }
.badge-rtp { color: var(--fc-green); }
.btn-info-round { width: 2rem; height: 2rem; border-radius: 50%; border: 2px solid var(--fc-gold); background: rgba(0,0,0,.45); color: var(--fc-gold); font-weight: 900; font-family: Georgia, serif; cursor: pointer; }
.popover { max-width: 520px; --bs-popover-bg: #1d0838; --bs-popover-border-color: rgba(255,204,0,.4); --bs-popover-header-bg: #2c0d52; --bs-popover-body-color: #eadcff; --bs-popover-header-color: #ffd23f; }
.pt-desc { font-size: .82rem; color: #dccbff; }
.paytable { width: 100%; font-size: .8rem; border-collapse: collapse; }
.paytable td { padding: .22rem .35rem; border-bottom: 1px solid rgba(255,255,255,.08); }
.pt-sym { font-size: 1.3rem; width: 2.2rem; text-align: center; }
.pt-sym .bar { display: block; font-size: .45rem; }
.pt-pays span { color: var(--fc-gold); font-weight: 800; }
.pt-note { font-size: .72rem; color: var(--fc-muted); margin: .5rem 0 0; }

.meters { display: flex; flex-wrap: wrap; gap: .5rem; margin: .7rem 0 .2rem; }
.meter { flex: 1 1 260px; display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: .6rem; background: rgba(0,0,0,.35); border-radius: 99px; padding: .3rem .8rem; border: 1px solid rgba(255,255,255,.12); }
.meter-label { font-size: .66rem; font-weight: 900; letter-spacing: 1.5px; color: #ffe8a3; }
.meter-bar { height: 10px; background: rgba(255,255,255,.12); border-radius: 99px; overflow: hidden; }
.meter-fill { height: 100%; background: linear-gradient(90deg, var(--fc-cyan), #9ef7ff); border-radius: 99px; transition: width .6s ease; }
.meter.heat .meter-fill { background: linear-gradient(90deg, #ffb400, #ff3d00); box-shadow: 0 0 10px #ff6a00; }
.meter.pearls .meter-fill { background: linear-gradient(90deg, #e6f7ff, #ffffff); box-shadow: 0 0 10px #bff; }
.meter.clock .meter-fill { background: linear-gradient(90deg, #8aa4ff, #ffd23f); }
.meter.freespins { border-color: var(--fc-gold); box-shadow: 0 0 14px rgba(255,204,0,.4); }
.meter.freespins .meter-fill { background: var(--gold-grad); }
.meter.map .meter-fill { background: linear-gradient(90deg, #00c2ff, #ffd23f); }
.meter.climb .meter-fill { background: linear-gradient(90deg, #3ddc84, #b6ff6e); }
.meter.boost { flex: 0 1 auto; }
.meter-text { font-size: .78rem; font-weight: 800; white-space: nowrap; font-variant-numeric: tabular-nums; }
.jp-pill { flex: 1 1 120px; }

.reels-wrap { position: relative; margin-top: .6rem; }
.reels-frame { border-radius: 1.2rem; padding: .7rem; background: linear-gradient(180deg, #000 0%, rgba(0,0,0,.75) 100%); box-shadow: inset 0 0 30px rgba(0,0,0,.9), 0 0 0 2px rgba(212, 175, 55, .7); }
.reels { display: grid; grid-template-columns: repeat(var(--reels), 1fr); gap: .55rem; }
.reel { display: grid; grid-template-rows: repeat(var(--rows), 1fr); gap: .55rem; border-radius: .9rem; padding: .1rem; position: relative; }
/* spinning: real cells hidden, a pre-rendered strip scrolls (transform only) */
.reel { overflow: hidden; }
.reel.spinning > .cell { visibility: hidden; }
.reel-strip { position: absolute; left: .1rem; right: .1rem; top: 0; display: flex; flex-direction: column; gap: .55rem; will-change: transform; animation: stripScroll .22s linear infinite; opacity: .9; }
body.turbo .reel-strip { animation-duration: .12s; }
.strip-cell { flex: 0 0 auto; height: clamp(64px, 14.5vh, 138px); border-radius: .85rem; display: flex; align-items: center; justify-content: center; background: rgba(255,255,255,.06); }
.slot-machine.rows-4 .strip-cell { height: clamp(54px, 11vh, 108px); }
.slot-machine.dual .strip-cell { height: clamp(58px, 12vh, 118px); }
.strip-cell .sym { filter: none; opacity: .85; }
.strip-cell.royal .sym { font-family: var(--display); color: #cfd8ff; }
@keyframes stripScroll { from { transform: translateY(-50%); } to { transform: translateY(0); } }
.reel.spinning::after { content: ""; position: absolute; inset: 0; pointer-events: none; background: linear-gradient(180deg, rgba(0,0,0,.55), transparent 25%, transparent 75%, rgba(0,0,0,.55)); }
.cell.shimmer .sym { animation: shimmer .16s linear infinite; }
@keyframes shimmer { 0% { transform: translateY(-8%); opacity: .55; } 100% { transform: translateY(8%); opacity: .55; } }
.cell {
  position: relative; height: clamp(64px, 14.5vh, 138px); border-radius: .85rem; display: flex; align-items: center; justify-content: center; overflow: hidden;
  background: radial-gradient(circle at 50% 30%, rgba(255,255,255,.2), rgba(255,255,255,.04) 55%, rgba(0,0,0,.25)), linear-gradient(180deg, rgba(255,255,255,.07), rgba(0,0,0,.25));
  box-shadow: inset 0 2px 0 rgba(255,255,255,.12), inset 0 -3px 8px rgba(0,0,0,.45);
  transition: opacity .25s, filter .25s, transform .2s;
}
.slot-machine.rows-4 .cell { height: clamp(54px, 11vh, 108px); }
.slot-machine.reels-3 { max-width: 760px; }
.slot-machine.dual .cell { height: clamp(58px, 12vh, 118px); }
.sym { font-size: clamp(1.8rem, min(5vw, 8.5vh), 3.8rem); line-height: 1; filter: drop-shadow(0 6px 6px rgba(0,0,0,.55)); user-select: none; }
.slot-machine.rows-4 .sym { font-size: clamp(1.6rem, min(4.4vw, 7vh), 3.2rem); }
.slot-machine.reels-3 .sym { font-size: clamp(2.2rem, min(7vw, 9vh), 4.4rem); }
.cell.royal .sym { font-family: var(--display); font-size: clamp(1.6rem, 4.4vw, 3.2rem); background: linear-gradient(180deg, #fff, #b8c6ff); -webkit-background-clip: text; background-clip: text; color: transparent; }
.cell.seven .sym { font-family: var(--display); font-size: clamp(2.4rem, 7vw, 5rem); -webkit-text-stroke: 2px #fff3; }
.cell.seven-red .sym { background: linear-gradient(180deg, #ff8a8a, #e0002a 60%, #8a0018); -webkit-background-clip: text; background-clip: text; color: transparent; }
.cell.seven-blue .sym { background: linear-gradient(180deg, #9ad7ff, #0077ff 60%, #003c8a); -webkit-background-clip: text; background-clip: text; color: transparent; }
.cell.bars .sym, .pt-sym.bars { display: flex; flex-direction: column; gap: 3px; }
.bar { display: block; font-family: var(--display); font-size: clamp(.55rem, 1.6vw, 1rem); line-height: 1; padding: .14em .5em; border-radius: .3em; background: #111; color: #ffd23f; border: 2px solid #ffd23f; font-weight: 400; }
.cell.blank .sym { opacity: 0; }
.cell.wild { background: radial-gradient(circle at 50% 35%, rgba(255,230,120,.5), rgba(255,160,0,.18) 55%, rgba(0,0,0,.3)); box-shadow: inset 0 0 0 2px rgba(255, 204, 0, .8), inset 0 0 18px rgba(255,204,0,.35); }
.cell.wild::after { content: "WILD"; position: absolute; bottom: 4%; left: 50%; transform: translateX(-50%); font-family: var(--display); font-size: clamp(.45rem, 1.1vw, .72rem); color: #2a1300; background: var(--gold-grad); padding: .05rem .45rem; border-radius: 99px; letter-spacing: 1px; box-shadow: 0 2px 6px rgba(0,0,0,.5); }
.cell.scatter { box-shadow: inset 0 0 0 2px rgba(0, 194, 255, .7), inset 0 0 18px rgba(0,194,255,.3); }
.cell.collect { box-shadow: inset 0 0 0 2px rgba(160, 255, 200, .6); }
.cell.mystery { background: linear-gradient(160deg, #4d2a8a, #1b0b3b); }
.cell.mystery .sym { font-family: var(--display); color: #ffd23f; }
.cell.ruby .sym { filter: hue-rotate(140deg) saturate(2.2) drop-shadow(0 0 10px rgba(255,0,70,.7)); }
.cell.blood-moon .sym { filter: sepia(1) saturate(6) hue-rotate(-40deg) drop-shadow(0 0 12px #f00); }
.cell.phoenix .sym { filter: sepia(.6) saturate(3) hue-rotate(-20deg) drop-shadow(0 0 10px #ff6a00); }
.cell.carriage { box-shadow: inset 0 0 0 2px #a8c4ff, inset 0 0 20px rgba(168,196,255,.5); }
.cell-badge:empty { display: none; }
.cell-badge { position: absolute; top: 5%; right: 6%; font-weight: 900; font-size: clamp(.6rem, 1.3vw, .85rem); padding: .05rem .4rem; border-radius: 99px; background: var(--pink-grad); color: #fff; box-shadow: 0 2px 6px rgba(0,0,0,.5); }
.cell.fireball .cell-badge, .cell.held .cell-badge { background: var(--gold-grad); color: #2a1300; font-size: clamp(.7rem, 1.6vw, 1rem); top: auto; bottom: 6%; right: 50%; transform: translateX(50%); }

.cell.land { animation: land .32s cubic-bezier(.3, 1.6, .5, 1); }
@keyframes land { 0% { transform: translateY(-18%); } 100% { transform: translateY(0); } }
.cell.win { animation: winPulse 1s ease-in-out infinite; z-index: 2; box-shadow: 0 0 0 3px var(--fc-gold), 0 0 24px rgba(255, 204, 0, .85), inset 0 0 20px rgba(255, 230, 120, .45); }
@keyframes winPulse { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.06); } }
.cell.dim { opacity: .38; filter: grayscale(.5); }
.cell.explode { animation: explode .36s ease-in forwards; }
@keyframes explode { to { transform: scale(1.5) rotate(12deg); opacity: 0; filter: brightness(3); } }
.cell.dropped { animation: drop .38s cubic-bezier(.3, 1.4, .5, 1); }
@keyframes drop { 0% { transform: translateY(-120%); opacity: 0; } 100% { transform: none; opacity: 1; } }
.cell.expanded, .cell.grow, .cell.dragon-reel, .cell.transform, .cell.reveal, .cell.revived, .cell.transfer { animation: morph .45s ease; }
@keyframes morph { 0% { transform: scale(.4) rotateY(90deg); filter: brightness(3); } 100% { transform: none; } }
.cell.expanded, .cell.dragon-reel { box-shadow: inset 0 0 0 3px #ffd23f, 0 0 20px rgba(255,120,0,.7); }
.cell.dragon-reel { background: radial-gradient(circle, rgba(255,90,0,.55), rgba(120,0,0,.5)); }
.cell.grow { background: radial-gradient(circle, rgba(120,255,80,.35), rgba(20,80,10,.4)); }
.cell.stone .sym { filter: grayscale(1) brightness(1.35) contrast(.9) drop-shadow(0 0 6px #cfe9c2); }
.cell.stone { background: linear-gradient(160deg, #6d7468, #2e332b); box-shadow: inset 0 0 0 2px #a9c79c; }
.cell.sticky { box-shadow: inset 0 0 0 3px #ff4fb0, 0 0 16px rgba(255, 79, 176, .7); }
.cell.held { box-shadow: inset 0 0 0 3px var(--fc-gold), 0 0 14px rgba(255, 204, 0, .6); }
.cell.new-held { animation: morph .45s ease; }
.cell.nudged { animation: nudge .45s ease; }
@keyframes nudge { 0% { transform: translateY(-35%); } 60% { transform: translateY(6%); } 100% { transform: none; } }
.cell.transfer { box-shadow: inset 0 0 0 3px #ff1744, 0 0 18px rgba(255, 23, 68, .8); }

.reel-note { position: absolute; left: 50%; top: -.6rem; transform: translate(-50%, -40%); z-index: 5; pointer-events: none; opacity: 0; font-family: var(--display); font-size: .95rem; color: #fff; padding: .3rem 1rem; border-radius: 99px; background: var(--pink-grad); box-shadow: 0 6px 20px rgba(0,0,0,.5); white-space: nowrap; }
.reel-note.show { animation: noteIn 2.4s ease forwards; }
@keyframes noteIn { 0% { opacity: 0; transform: translate(-50%, -10%) scale(.8); } 12% { opacity: 1; transform: translate(-50%, -40%) scale(1.05); } 80% { opacity: 1; } 100% { opacity: 0; } }
.win-banner { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; pointer-events: none; z-index: 6; opacity: 0; }
.win-banner.show { opacity: 1; animation: bannerIn .35s cubic-bezier(.3, 1.6, .5, 1); }
.win-banner { font-family: var(--display); font-size: clamp(1.6rem, 5vw, 3.2rem); color: #fff; text-shadow: 0 4px 0 #7a004a, 0 0 30px rgba(255, 46, 136, .9); }
.win-banner b { background: var(--gold-grad); -webkit-background-clip: text; background-clip: text; color: transparent; font-weight: 400; text-shadow: none; filter: drop-shadow(0 4px 0 #7a3b00); margin-left: .3em; }
.win-banner.small { font-size: clamp(1.2rem, 3.4vw, 2.2rem); }
@keyframes bannerIn { 0% { transform: scale(.3); } 100% { transform: scale(1); } }

.sm-controls { display: grid; grid-template-columns: 1.3fr 1fr 1.2fr; gap: .8rem; align-items: center; margin-top: .9rem; }
.ctl-group { display: flex; flex-direction: column; align-items: center; gap: .25rem; background: rgba(0,0,0,.35); border-radius: 1rem; padding: .5rem .7rem; border: 1px solid rgba(255,255,255,.1); }
.bet-group { flex-direction: row; flex-wrap: wrap; justify-content: center; gap: .45rem; }
.bet-group .ctl-label { width: 100%; text-align: center; }
.bet-stepper { display: flex; align-items: center; gap: .35rem; }
.btn-step { width: 2.3rem; height: 2.3rem; border-radius: 50%; border: none; font-size: 1.3rem; font-weight: 900; line-height: 1; background: linear-gradient(180deg, #6d35b8, #3b1670); color: #fff; box-shadow: 0 3px 0 #220a45; padding: 0; }
.btn-step:hover { filter: brightness(1.2); color: #fff; }
.bet-val { min-width: 6.5rem; text-align: center; font-family: var(--display); font-size: 1.2rem; color: var(--fc-gold); }
.btn-maxbet { border: none; border-radius: 99px; padding: .4rem .9rem; font-weight: 900; font-size: .75rem; background: var(--gold-grad); color: #2a1300; box-shadow: 0 3px 0 #a35f00; }
.win-val { font-family: var(--display); font-size: 1.7rem; background: var(--gold-grad); -webkit-background-clip: text; background-clip: text; color: transparent; font-variant-numeric: tabular-nums; }
.spin-group { flex-direction: row; justify-content: center; gap: .7rem; }
.btn-spin {
  width: 6.4rem; height: 6.4rem; border-radius: 50%; border: 4px solid #ffe38a; padding: 0; font-family: var(--display); font-size: 1.35rem; color: #fff;
  background: radial-gradient(circle at 50% 30%, #7dffb2, #16c172 45%, #07683b 100%);
  box-shadow: 0 7px 0 #04432a, 0 0 30px rgba(31, 209, 139, .55), inset 0 -6px 14px rgba(0,0,0,.3); text-shadow: 0 2px 0 rgba(0,0,0,.4);
  transition: transform .1s, filter .2s; margin-top: -1.6rem;
}
.btn-spin:hover { filter: brightness(1.08); color: #fff; transform: scale(1.04); }
.btn-spin:active { transform: translateY(5px); box-shadow: 0 2px 0 #04432a; }
.btn-spin.busy { filter: grayscale(.6) brightness(.8); pointer-events: none; }
.btn-spin.free { background: radial-gradient(circle at 50% 30%, #fff3a8, #ffb300 45%, #a35f00 100%); box-shadow: 0 7px 0 #5c3500, 0 0 30px rgba(255, 204, 0, .65); color: #3a1a00; text-shadow: none; }
.spin-label small { display: block; font-family: 'Poppins', sans-serif; font-size: .62rem; font-weight: 800; }
.btn-auto { border: 2px solid rgba(255,255,255,.25); background: rgba(255,255,255,.06); color: #fff; border-radius: 99px; padding: .45rem .9rem; font-weight: 900; font-size: .78rem; cursor: pointer; }
.btn-auto.on { background: var(--pink-grad); border-color: transparent; box-shadow: 0 0 18px rgba(255, 46, 136, .6); }
.sm-status { margin-top: .7rem; min-height: 1.6rem; font-size: .82rem; }
.status-line, .status-idle { display: flex; flex-wrap: wrap; gap: .6rem; align-items: center; justify-content: center; color: rgba(255,255,255,.8); }
.st-win { color: var(--fc-gold); font-weight: 900; }
.st-lose { color: var(--fc-muted); }
.st-fs { color: #1a0933; background: var(--gold-grad); border-radius: 99px; padding: .05rem .6rem; font-weight: 900; }
.st-parts { color: rgba(255,255,255,.65); font-size: .75rem; }

/* bonus overlays */
/* uiOutput() containers are display:contents in current Shiny, so styling
   lives on wrapper divs; the overlay hides itself when no bonus is rendered */
.bonus-layer:not(:has(.bonus-panel)) { display: none; }
.bonus-layer { position: absolute; inset: -.3rem; z-index: 8; display: flex; align-items: center; justify-content: center; background: radial-gradient(circle at 50% 40%, rgba(40, 10, 80, .9), rgba(8, 2, 20, .94)); border-radius: 1.3rem; }
/* no continuous animations underneath an open bonus (keeps repaints cheap) */
.reels-wrap:has(.bonus-panel) .cell.win { animation: none; }
.bonus-panel { text-align: center; padding: 1rem; width: 100%; max-width: 640px; animation: bannerIn .35s ease; }
.bonus-title { font-family: var(--display); font-size: 1.8rem; background: var(--gold-grad); -webkit-background-clip: text; background-clip: text; color: transparent; }
.bonus-sub { color: #eadcff; margin-bottom: .8rem; font-size: .9rem; }
.bonus-status { margin-top: .7rem; color: #ffe8a3; font-weight: 700; font-size: .88rem; }
.bonus-tiles { display: grid; gap: .6rem; margin: 0 auto; }
.bonus-tiles.grid-3 { grid-template-columns: repeat(3, 1fr); max-width: 420px; }
.bonus-tiles.grid-3x3 { grid-template-columns: repeat(3, 1fr); max-width: 380px; }
.bonus-tiles.grid-4x3 { grid-template-columns: repeat(4, 1fr); max-width: 520px; }
.bonus-tile { aspect-ratio: 1.25; border-radius: 1rem; border: 2px solid rgba(255, 204, 0, .5); background: radial-gradient(circle at 50% 30%, #6a2cc0, #2a0b55); cursor: pointer; display: flex; align-items: center; justify-content: center; font-size: 2rem; color: #fff; transition: transform .12s, box-shadow .2s; }
button.bonus-tile:hover { transform: translateY(-3px) scale(1.04); box-shadow: 0 0 24px rgba(255, 204, 0, .6); }
.bonus-tile.revealed { animation: flipIn .4s ease; background: linear-gradient(160deg, #fff3a8, #ffb300); color: #2a1300; font-weight: 900; }
.bonus-tile.revealed .bt-label { font-size: clamp(.75rem, 1.6vw, 1.05rem); }
.bonus-tile.collect, .bonus-tile.trap { background: linear-gradient(160deg, #ff6b81, #b0002a); color: #fff; }
.bonus-tile.mult { background: linear-gradient(160deg, #7df9ff, #00a6c8); }
.bonus-tile.unpicked { opacity: .45; filter: grayscale(.4); animation: none; }
@keyframes flipIn { 0% { transform: rotateY(90deg); } 100% { transform: rotateY(0); } }
.vol-options { display: grid; grid-template-columns: repeat(3, 1fr); gap: .7rem; }
.vol-option { border-radius: 1rem; padding: 1rem .6rem; border: 2px solid rgba(255,204,0,.45); background: linear-gradient(160deg, #8a4a00, #2b1500); color: #fff; cursor: pointer; transition: transform .15s; }
.vol-option:hover { transform: translateY(-4px); box-shadow: 0 0 24px rgba(255,150,0,.6); }
.vol-option.chosen { background: var(--gold-grad); color: #2a1300; }
.vo-tiger { font-size: 1.6rem; }
.vo-label { font-weight: 900; margin-top: .3rem; }
.vo-sub { font-size: .72rem; opacity: .8; }
.bonus-done { margin-top: .9rem; animation: fadeUp .4s ease both; }
.bonus-wheel.done .bonus-done { animation-delay: 4.3s; }
body.turbo .bonus-wheel.done .bonus-done { animation-delay: 2s; }
.bonus-total { font-family: var(--display); font-size: 2rem; color: var(--fc-gold); margin-bottom: .5rem; }
@keyframes fadeUp { 0% { opacity: 0; transform: translateY(10px); } 100% { opacity: 1; transform: none; } }
.top-screen { margin-top: .8rem; border-radius: 1.2rem; min-height: 150px; padding: .8rem; background: linear-gradient(180deg, #3b2410, #1a0f05); border: 2px solid #8a5a22; box-shadow: inset 0 0 30px rgba(0,0,0,.7); }
.top-screen .bonus-panel { max-width: none; }
.top-screen-idle { text-align: center; color: #f0c98a; }
.ts-title { font-family: var(--display); font-size: 1.2rem; }
.ts-sub { font-size: .8rem; opacity: .8; }
.ts-bottles { font-size: 1.6rem; letter-spacing: .3rem; margin-top: .4rem; opacity: .75; }

/* prize wheels */
.prize-wheel { position: relative; display: inline-block; margin: .4rem auto; }
.prize-wheel .wheel-svg { display: block; max-width: 100%; height: auto; filter: drop-shadow(0 10px 30px rgba(0,0,0,.6)); border-radius: 50%; box-shadow: 0 0 0 6px #d4af37, 0 0 0 10px #3b1b00, 0 0 40px rgba(255, 204, 0, .35); }
.wheel-rotor { transform-box: fill-box; transform-origin: 50% 50%; }
.wheel-pointer { position: absolute; top: -14px; left: 50%; transform: translateX(-50%); width: 0; height: 0; border-left: 16px solid transparent; border-right: 16px solid transparent; border-top: 30px solid #ffd23f; z-index: 3; filter: drop-shadow(0 3px 4px rgba(0,0,0,.6)); }
.wheel-hub { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); color: #ffd23f; font-size: 1.6rem; pointer-events: none; }
.prize-wheel.landed .wheel-svg { animation: wheelFlash .9s ease 2; }
@keyframes wheelFlash { 50% { box-shadow: 0 0 0 6px #fff, 0 0 0 10px #ffd23f, 0 0 60px rgba(255, 204, 0, .9); } }

/* ------------------------------------------------------------- table games */
.table-game { max-width: 1180px; margin: 0 auto 3rem; }
.felt {
  border-radius: 220px 220px 1.6rem 1.6rem / 120px 120px 1.6rem 1.6rem; padding: 1.6rem 1.4rem 1.2rem; position: relative; min-height: 360px;
  background: radial-gradient(ellipse at 50% 20%, #1b8a55 0%, #0d5c37 55%, #063a22 100%);
  border: 10px solid #4a2a10; box-shadow: 0 0 0 3px #d4af37, 0 25px 60px rgba(0,0,0,.6), inset 0 0 60px rgba(0,0,0,.5);
}
.bj-empty { text-align: center; padding: 4.5rem 1rem; color: rgba(255,255,255,.75); }
.bj-logo { font-family: var(--display); font-size: 2rem; color: rgba(255, 230, 160, .85); }
.bj-sub { font-size: 1rem; letter-spacing: 3px; text-transform: uppercase; }
.bj-layout { display: flex; flex-direction: column; align-items: center; gap: .8rem; }
.bj-dealer, .bj-hand { display: flex; flex-direction: column; align-items: center; gap: .45rem; }
.hand-label { font-weight: 900; letter-spacing: 3px; font-size: .78rem; color: rgba(255,255,255,.85); display: flex; gap: .5rem; align-items: center; }
.hand-total { background: rgba(0,0,0,.55); border-radius: 99px; padding: .1rem .6rem; font-weight: 900; color: #fff; letter-spacing: 0; font-size: .85rem; }
.cards { display: flex; gap: .45rem; min-height: 122px; }
.bj-hands { display: flex; gap: 1.6rem; flex-wrap: wrap; justify-content: center; margin-top: .6rem; }
.bj-hand { padding: .6rem .8rem; border-radius: 1rem; border: 2px dashed transparent; transition: all .2s; }
.bj-hand.active { border-color: var(--fc-gold); background: rgba(255, 204, 0, .08); box-shadow: 0 0 24px rgba(255,204,0,.25); }
.bj-hand.res-win { background: rgba(31, 209, 139, .15); border-color: var(--fc-green); border-style: solid; }
.bj-hand.res-lose { opacity: .75; }
.bj-hand.res-push { border-color: #8fd3ff; border-style: solid; }
.hand-meta { display: flex; gap: .5rem; align-items: center; flex-wrap: wrap; justify-content: center; }
.hand-bet { font-size: .78rem; color: #ffe8a3; font-weight: 800; }
.hand-result { font-weight: 900; font-size: .8rem; padding: .1rem .6rem; border-radius: 99px; background: #fff; color: #0d5c37; }
.res-lose .hand-result { background: #ff4d6d; color: #fff; }
.shoe-info { font-size: .72rem; color: rgba(255,255,255,.6); }
.side-result { font-weight: 800; color: rgba(255,255,255,.7); }
.side-result.hit { color: var(--fc-gold); text-shadow: 0 0 10px rgba(255,204,0,.7); }
.felt-message { text-align: center; margin-top: 1rem; font-weight: 700; color: #fff; min-height: 1.6rem; display: flex; gap: .6rem; justify-content: center; align-items: center; flex-wrap: wrap; }
.hint-pill { background: rgba(0,0,0,.45); border: 1px solid var(--fc-cyan); color: #9ef7ff; border-radius: 99px; padding: .1rem .7rem; font-size: .78rem; }
.ghost { opacity: .35; display: flex; align-items: center; justify-content: center; font-size: .6rem; text-align: center; color: #fff; border: 2px dashed #fff !important; background: transparent !important; }

.pcard {
  width: 84px; height: 118px; border-radius: 10px; background: linear-gradient(160deg, #ffffff, #f1eadf); position: relative; flex: 0 0 auto;
  box-shadow: 0 6px 14px rgba(0,0,0,.45), inset 0 0 0 1px rgba(0,0,0,.08); font-family: Georgia, 'Times New Roman', serif; user-select: none;
}
.pcard.red { color: #d10f2f; } .pcard.black { color: #14121a; }
.pc-corner { position: absolute; font-weight: 700; font-size: 1.05rem; line-height: 1; text-align: center; }
.pc-corner.tl { top: 6px; left: 7px; } .pc-corner.br { bottom: 6px; right: 7px; transform: rotate(180deg); }
.pc-center { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-size: 2.6rem; }
.pcard.back { background: repeating-linear-gradient(45deg, #7b1b8f 0 8px, #5a0f6b 8px 16px); border: 4px solid #fff; }
.pcard-back-inner { position: absolute; inset: 8px; border: 2px solid rgba(255, 204, 0, .7); border-radius: 6px; }
.pcard.joker { color: #7b2cbf; } .pcard.joker .pc-center { font-size: 3rem; } .pcard.joker .pc-corner { top: 6px; left: 7px; font-size: .8rem; }
.pcard.switched { box-shadow: 0 0 0 3px var(--fc-gold), 0 6px 14px rgba(0,0,0,.45); }
.deal-in { animation: dealIn .42s cubic-bezier(.2, 1.2, .4, 1) both; }
.deal-in.d2 { animation-delay: .12s; } .deal-in.d3 { animation-delay: .24s; } .deal-in.d4 { animation-delay: .36s; } .deal-in.d5 { animation-delay: .48s; } .deal-in.d6 { animation-delay: .6s; }
@keyframes dealIn { 0% { transform: translate(160px, -200px) rotate(25deg); opacity: 0; } 100% { transform: none; opacity: 1; } }
body.turbo .deal-in { animation-duration: .18s; animation-delay: 0s !important; }

.table-controls { margin-top: 1rem; display: flex; flex-direction: column; gap: .7rem; align-items: center; }
.action-row { display: flex; gap: .6rem; flex-wrap: wrap; justify-content: center; align-items: center; min-height: 3rem; }
.bet-row { display: flex; gap: 1rem; align-items: center; flex-wrap: wrap; justify-content: center; }
.bet-chips { display: flex; align-items: center; gap: .45rem; flex-wrap: wrap; }
.bet-info { display: flex; flex-direction: column; align-items: center; }
.bet-amount { font-family: var(--display); color: var(--fc-gold); font-size: 1.2rem; }
.bet-sub { font-size: .7rem; color: var(--fc-muted); }
.chip {
  width: 3.1rem; height: 3.1rem; border-radius: 50%; border: 4px dashed rgba(255,255,255,.85); color: #fff; font-weight: 900; font-size: .72rem; cursor: pointer; position: relative;
  box-shadow: 0 4px 0 rgba(0,0,0,.45), inset 0 0 0 4px rgba(0,0,0,.15); transition: transform .12s; padding: 0;
}
.chip:hover { transform: translateY(-3px) rotate(8deg); }
.chip.selected { transform: translateY(-6px) scale(1.08); box-shadow: 0 0 0 3px var(--fc-gold), 0 0 18px rgba(255,204,0,.8); }
.chip-red { background: #d91e36; } .chip-green { background: #12a150; } .chip-blue { background: #1769d6; }
.chip-orange { background: #f07b11; } .chip-purple { background: #7b2cbf; } .chip-black { background: #1d1d1f; }

/* video poker */
.vp-machine { border-radius: 1.6rem; padding: 1rem; background: linear-gradient(180deg, #0d2f6b, #061330); border: 3px solid #d4af37; box-shadow: 0 0 40px rgba(0, 120, 255, .25), 0 25px 60px rgba(0,0,0,.6); }
.vp-paytable { width: 100%; border-collapse: separate; border-spacing: 0; font-size: .82rem; background: #000a3a; border-radius: .8rem; overflow: hidden; border: 2px solid #ffd23f; }
.vp-paytable th, .vp-paytable td { padding: .22rem .6rem; text-align: right; color: #ffd23f; font-weight: 800; }
.vp-paytable th:first-child, .vp-paytable td:first-child { text-align: left; color: #ffe98a; }
.vp-paytable thead th { background: #001466; color: #fff; }
.vp-paytable .col-active { background: rgba(255, 46, 136, .45); color: #fff; }
.vp-paytable tr.row-hit td { background: #ffd23f; color: #061330; animation: rowFlash .8s ease 3; }
@keyframes rowFlash { 50% { background: #fff; } }
.vp-screen { margin: 1rem 0; }
.vp-cards { display: flex; justify-content: center; gap: .8rem; flex-wrap: wrap; }
.vp-cards .pcard { width: 112px; height: 156px; }
.vp-cards .pc-center { font-size: 3.3rem; }
.pcard.clickable { cursor: pointer; transition: transform .12s; }
.pcard.clickable:hover { transform: translateY(-6px); }
.pcard.held { transform: translateY(-10px); box-shadow: 0 0 0 4px var(--fc-gold), 0 10px 24px rgba(255, 204, 0, .4); }
.held-tag { position: absolute; bottom: -1.6rem; left: 50%; transform: translateX(-50%); background: var(--gold-grad); color: #2a1300; font-family: var(--display); font-size: .8rem; padding: .05rem .7rem; border-radius: 99px; }
.vp-message { text-align: center; margin-top: 2rem; font-weight: 800; min-height: 1.5rem; }
.vp-win { color: var(--fc-gold); font-size: 1.15rem; text-shadow: 0 0 14px rgba(255, 204, 0, .7); }
.vp-controls { display: grid; grid-template-columns: minmax(370px, 2.3fr) 1.3fr 1fr 1fr 1fr; gap: .7rem; align-items: stretch; }
.vp-controls .bet-amount { display: flex; flex-direction: column; align-items: center; line-height: 1.15; }
.vp-bet-formula { font-family: 'Poppins', sans-serif; font-size: .72rem; color: var(--fc-muted); font-weight: 700; white-space: nowrap; }
.vp-controls .ctl-group { justify-content: center; }
.vp-coin-btns { display: flex; gap: .4rem; }

/* roulette */
.rl-layout { display: grid; grid-template-columns: minmax(260px, 360px) 1fr; gap: 1.2rem; align-items: start; }
.rl-wheel-area { display: flex; flex-direction: column; align-items: center; gap: .8rem; background: var(--fc-panel); border-radius: 1.4rem; padding: 1rem; border: 1px solid rgba(255,255,255,.1); }
.rl-wheels { display: grid; gap: .6rem; justify-items: center; }
.rl-wheels.n2 { grid-template-columns: repeat(2, 1fr); }
.rl-wheels.n3, .rl-wheels.n4 { grid-template-columns: repeat(2, 1fr); }
.rl-wheels.n5, .rl-wheels.n6 { grid-template-columns: repeat(2, 1fr); }
.rl-wheel { position: relative; }
.rl-wheel svg { display: block; filter: drop-shadow(0 12px 24px rgba(0,0,0,.6)); }
.rl-rotor { transform-box: fill-box; transform-origin: 50% 50%; }
.rl-ball-track { position: absolute; inset: 0; pointer-events: none; }
.rl-ball { position: absolute; top: 12%; left: 50%; width: 7%; height: 7%; min-width: 8px; min-height: 8px; transform: translateX(-50%); border-radius: 50%; background: radial-gradient(circle at 35% 30%, #fff, #c9c9c9 60%, #777); box-shadow: 0 2px 4px rgba(0,0,0,.6); }
.rl-wheel::before { content: ""; position: absolute; top: -6px; left: 50%; transform: translateX(-50%); border-left: 9px solid transparent; border-right: 9px solid transparent; border-top: 16px solid #ffd23f; z-index: 3; }
.rl-result-bubble { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%) scale(0); width: 30%; height: 30%; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-family: var(--display); font-size: 1.3rem; color: #fff; border: 3px solid #ffd23f; transition: transform .3s cubic-bezier(.3, 1.6, .5, 1); }
.rl-result-bubble.show { transform: translate(-50%, -50%) scale(1); }
.rl-result-bubble.red { background: #c0142b; } .rl-result-bubble.black { background: #15121c; } .rl-result-bubble.green { background: #0d8a3e; }
.rl-last { width: 100%; min-height: 4rem; text-align: center; }
.rl-last-empty { color: var(--fc-muted); }
.rl-last-nums { display: flex; gap: .4rem; justify-content: center; flex-wrap: wrap; }
.rl-ball-num, .rl-hist { display: inline-flex; align-items: center; justify-content: center; border-radius: 50%; font-weight: 900; color: #fff; }
.rl-ball-num { width: 2.6rem; height: 2.6rem; font-size: 1.05rem; border: 2px solid #ffd23f; animation: bannerIn .35s ease; }
.rl-ball-num.red, .rl-hist.red { background: #c0142b; } .rl-ball-num.black, .rl-hist.black { background: #1f1b27; } .rl-ball-num.green, .rl-hist.green { background: #0d8a3e; }
.rl-net { margin-top: .5rem; font-weight: 800; } .rl-net.up { color: var(--fc-green); } .rl-net.down { color: var(--fc-red); }
.rl-net span { font-weight: 600; font-size: .82rem; }
.rl-win-lines { font-size: .78rem; color: #eadcff; margin-top: .3rem; max-height: 140px; overflow: auto; }
.rl-win-lines div { display: flex; justify-content: space-between; gap: .6rem; border-bottom: 1px solid rgba(255,255,255,.06); padding: .1rem 0; }
.rl-win-lines span { color: var(--fc-gold); font-weight: 800; }
.rl-history { display: flex; flex-wrap: wrap; gap: .25rem; justify-content: center; }
.rl-hist { width: 1.7rem; height: 1.7rem; font-size: .7rem; }
.rl-board { background: radial-gradient(ellipse at 50% 20%, #1b8a55 0%, #0d5c37 60%, #063a22 100%); border-radius: 1.4rem; padding: 1rem; border: 8px solid #4a2a10; box-shadow: 0 0 0 3px #d4af37, 0 25px 60px rgba(0,0,0,.6); }
.rl-table { display: grid; grid-template-columns: 1fr 12fr 1fr; grid-template-rows: 3fr 1fr 1fr; gap: 0; user-select: none; }
.rl-zero { grid-column: 1; grid-row: 1; display: flex; flex-direction: column; position: relative; }
.rl-zero .rl-num { flex: 1; border-radius: 50% 0 0 50% / 30% 0 0 30%; }
.rl-zero.double .rl-num:first-child { border-radius: 50% 0 0 0 / 30% 0 0 0; } .rl-zero.double .rl-num:nth-child(2) { border-radius: 0 0 0 50% / 0 0 0 30%; }
.rl-grid { grid-column: 2; grid-row: 1; display: grid; grid-template-columns: repeat(12, 1fr); grid-template-rows: repeat(3, 1fr); position: relative; }
.rl-num, .rl-out { position: relative; display: flex; align-items: center; justify-content: center; border: 1.5px solid rgba(255,255,255,.75); color: #fff; font-weight: 800; cursor: pointer; min-height: 3rem; transition: background .15s, box-shadow .15s; font-size: .95rem; }
.rl-num span { pointer-events: none; }
.rl-num.red { background: #b3122a; } .rl-num.black { background: #17141d; } .rl-num.green { background: #0b7a37; }
.rl-num:hover, .rl-out:hover { box-shadow: inset 0 0 0 3px #ffd23f; filter: brightness(1.2); }
.rl-cols { grid-column: 3; grid-row: 1; display: grid; grid-template-rows: repeat(3, 1fr); }
.rl-dozens { grid-column: 2; grid-row: 2; display: grid; grid-template-columns: repeat(3, 1fr); }
.rl-outside { grid-column: 2; grid-row: 3; display: grid; grid-template-columns: repeat(6, 1fr); }
.rl-out { background: transparent; font-size: .85rem; min-height: 2.6rem; }
.rl-out.red span { color: #ff3048; font-size: 1.5rem; } .rl-out.black span { color: #000; font-size: 1.5rem; -webkit-text-stroke: 1px #fff; }
.rl-spot { position: absolute; width: 18px; height: 18px; margin: -9px 0 0 -9px; border-radius: 50%; z-index: 4; cursor: pointer; background: rgba(255, 255, 255, 0); transition: background .12s, transform .12s; }
.rl-spot:hover { background: rgba(255, 210, 63, .85); transform: scale(1.25); box-shadow: 0 0 10px #ffd23f; }
.rl-spot.split-zero { width: 22px; height: 22px; margin: -11px 0 0 -11px; }
.rl-chip { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); min-width: 1.9rem; height: 1.9rem; padding: 0 .2rem; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: .58rem; font-weight: 900; color: #fff; border: 3px dashed rgba(255,255,255,.9); box-shadow: 0 3px 6px rgba(0,0,0,.6); z-index: 5; pointer-events: none; animation: chipIn .25s cubic-bezier(.3, 1.6, .5, 1); }
.rl-spot .rl-chip { min-width: 1.6rem; height: 1.6rem; font-size: .5rem; }
@keyframes chipIn { 0% { transform: translate(-50%, -80%) scale(.4); opacity: 0; } 100% { transform: translate(-50%, -50%) scale(1); opacity: 1; } }
.call-bets { display: flex; gap: .5rem; flex-wrap: wrap; align-items: center; justify-content: center; margin-top: .8rem; }
.btn-call { background: rgba(0,0,0,.45); color: #ffe8a3; border: 1px solid #d4af37; padding: .35rem .8rem; font-size: .78rem; }
.btn-call span { display: block; font-size: .62rem; color: #c9b37a; font-weight: 600; }
.btn-call:hover { background: #d4af37; color: #1a0f00; }
.multi-ctl { display: flex; align-items: center; gap: .5rem; }
.multi-ctl .shiny-options-group { display: flex; gap: .3rem; }
.multi-ctl .form-check-label, .multi-ctl label > span { padding: .25rem .65rem; }

/* -------------------------------------------------------------- meta pages */
.meta-page { max-width: 1200px; margin: 0 auto 3rem; }
.album-actions { display: flex; align-items: center; gap: .8rem; flex-wrap: wrap; }
.album-bar { width: 220px; height: 20px; }
.album-hint { background: var(--fc-panel); border-radius: 1rem; padding: .8rem 1rem; color: #dccbff; font-size: .88rem; margin-bottom: 1rem; border: 1px dashed rgba(255,255,255,.2); }
.recent-pulls { display: flex; align-items: center; gap: .4rem; flex-wrap: wrap; margin-bottom: 1rem; }
.mini-card { font-size: 1.5rem; width: 2.4rem; height: 3rem; display: inline-flex; align-items: center; justify-content: center; background: linear-gradient(160deg, #3b1670, #1d0838); border-radius: .4rem; border: 1px solid rgba(255,255,255,.2); }
.mini-card.lucky { border-color: var(--fc-gold); box-shadow: 0 0 10px rgba(255,204,0,.6); }
.album-sets { display: grid; grid-template-columns: repeat(auto-fill, minmax(480px, 1fr)); gap: 1rem; }
.album-set { background: var(--fc-panel); border-radius: 1.2rem; padding: .9rem; border: 1px solid rgba(255,255,255,.1); }
.album-set.complete { border-color: var(--fc-green); box-shadow: 0 0 22px rgba(31, 209, 139, .25); }
.set-head { display: flex; align-items: center; gap: .6rem; margin-bottom: .6rem; }
.set-icon { font-size: 1.8rem; }
.set-name { font-family: var(--display); font-size: .95rem; flex: 1; }
.set-count { margin-left: .5rem; font-family: 'Poppins', sans-serif; color: var(--fc-muted); font-size: .78rem; }
.set-reward { font-weight: 800; color: var(--fc-gold); font-size: .85rem; }
.set-cards { display: grid; grid-template-columns: repeat(9, minmax(0, 1fr)); gap: .35rem; }
.album-card { position: relative; min-width: 0; aspect-ratio: .72; border-radius: .45rem; background: linear-gradient(160deg, #4a1d86, #1c0838); border: 1px solid rgba(255,255,255,.18); display: flex; flex-direction: column; align-items: center; justify-content: center; padding: .15rem; text-align: center; }
.album-card.missing { background: rgba(255,255,255,.04); border-style: dashed; }
.album-card.missing .ac-glyph { color: rgba(255,255,255,.25); font-family: var(--display); font-size: 1rem; }
.album-card.lucky.owned { border: 2px solid var(--fc-gold); box-shadow: 0 0 10px rgba(255,204,0,.55); background: linear-gradient(160deg, #7a5a00, #2b1a00); }
.album-card.lucky.missing { border-color: rgba(255, 204, 0, .5); }
.album-card.s5.owned { background: linear-gradient(160deg, #b3127a, #3b0a5e); }
.album-card.s4.owned { background: linear-gradient(160deg, #1565c0, #1c0838); }
.ac-glyph { font-size: clamp(1rem, 2.3vw, 1.45rem); }
.ac-name { font-size: .5rem; line-height: 1.05; color: #eadcff; margin-top: .1rem; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ac-stars { font-size: .42rem; color: var(--fc-gold); letter-spacing: -1px; }
.ac-count { position: absolute; top: -6px; right: -6px; background: var(--pink-grad); color: #fff; font-size: .55rem; font-weight: 900; border-radius: 99px; padding: 0 .3rem; }

.modal-content:has(.lucky-board) { background: radial-gradient(circle at 50% 0%, #7a5a00, #1d0838 70%); border: 3px solid var(--fc-gold); border-radius: 1.6rem; color: #fff; }
.lucky-board { text-align: center; padding: .5rem; }
.lucky-title { font-family: var(--display); font-size: 1.8rem; background: var(--gold-grad); -webkit-background-clip: text; background-clip: text; color: transparent; }
.lucky-sub { color: #f6e6ff; margin-bottom: 1rem; }
.lucky-cards { display: flex; justify-content: center; gap: .9rem; margin-bottom: 1rem; }
.lucky-card { width: 130px; height: 180px; border-radius: 1rem; border: 3px solid var(--fc-gold); background: repeating-linear-gradient(45deg, #1b7a3a 0 10px, #14602d 10px 20px); font-size: 2.8rem; cursor: pointer; display: flex; align-items: center; justify-content: center; color: #fff; transition: transform .15s; }
button.lucky-card:hover { transform: translateY(-6px) rotate(-2deg); box-shadow: 0 0 30px rgba(255, 204, 0, .6); }
.lucky-card.flipped { background: linear-gradient(160deg, #fff3a8, #ffb300); color: #2a1300; font-size: .95rem; font-weight: 900; padding: .6rem; animation: flipIn .45s ease; opacity: .55; }
.lucky-card.flipped.chosen { opacity: 1; transform: scale(1.08); box-shadow: 0 0 30px rgba(255, 204, 0, .8); }

.wheels-row { display: grid; grid-template-columns: repeat(auto-fit, minmax(340px, 1fr)); gap: 1.2rem; }
.wheel-card { text-align: center; background: var(--fc-panel); border-radius: 1.5rem; padding: 1.2rem; border: 1px solid rgba(255,255,255,.1); }
.wheel-card.daily { background: radial-gradient(circle at 50% 0%, rgba(255, 204, 0, .22), transparent 60%), var(--fc-panel); border-color: rgba(255,204,0,.4); }
.wc-title { font-family: var(--display); color: #ffe8a3; margin-bottom: .4rem; }
.wheel-wait { display: flex; flex-direction: column; gap: .1rem; margin-top: .6rem; color: var(--fc-muted); }
.wheel-wait strong { font-family: var(--display); font-size: 1.5rem; color: #fff; font-weight: 400; }
.wheel-won { color: var(--fc-gold); font-weight: 800; }
.mult-ring { display: flex; justify-content: center; gap: .4rem; margin: .4rem 0 .8rem; }
.mult-chip { border: 1px solid rgba(255,204,0,.5); border-radius: 99px; padding: .1rem .6rem; font-weight: 900; color: #ffe8a3; }
.mult-chip.hit { background: var(--gold-grad); color: #2a1300; animation: bannerIn .4s ease 4.3s both; }

.star-balance { display: flex; align-items: center; gap: .8rem; }
.sb-stars { font-family: var(--display); font-size: 1.5rem; color: var(--fc-gold); }
.market-section { margin: 1rem 0 .6rem; font-size: 1.05rem; color: #fff; }
.market-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: .8rem; }
.market-item { background: var(--fc-panel); border-radius: 1.1rem; padding: 1rem .8rem; text-align: center; border: 1px solid rgba(255,255,255,.1); display: flex; flex-direction: column; gap: .25rem; align-items: center; transition: transform .15s; }
.market-item:hover { transform: translateY(-3px); border-color: rgba(255,204,0,.5); }
.market-item.owned { border-color: var(--fc-green); }
.market-item.active { box-shadow: 0 0 20px rgba(31, 209, 139, .45); }
.mi-icon { font-size: 2.4rem; }
.mi-name { font-weight: 800; }
.mi-desc { font-size: .75rem; color: var(--fc-muted); min-height: 2.2em; }
.btn-buy { background: var(--gold-grad); color: #2a1300; padding: .35rem 1rem; font-size: .8rem; margin-top: .3rem; box-shadow: 0 3px 0 #a35f00; }
.market-item.owned .btn-buy { background: linear-gradient(180deg, #2df5a3, #10a36a); box-shadow: 0 3px 0 #06613e; }
.boost-strip { display: flex; gap: .5rem; flex-wrap: wrap; }
.boost-pill { background: rgba(0, 194, 255, .15); border: 1px solid var(--fc-cyan); border-radius: 99px; padding: .2rem .8rem; font-weight: 700; font-size: .82rem; }
.avatar-row { display: flex; align-items: center; gap: .4rem; flex-wrap: wrap; margin-top: 1.2rem; }
.avatar-pick { font-size: 1.6rem; width: 3rem; height: 3rem; border-radius: 50%; border: 2px solid rgba(255,255,255,.2); background: rgba(255,255,255,.05); cursor: pointer; }
.avatar-pick.active { border-color: var(--fc-gold); box-shadow: 0 0 14px rgba(255,204,0,.6); }

.monster-map { position: relative; display: flex; flex-direction: column; gap: 1.2rem; padding-left: 2.6rem; }
.monster-map::before { content: ""; position: absolute; left: 1.7rem; top: 1rem; bottom: 1rem; width: 6px; border-radius: 6px; background: repeating-linear-gradient(180deg, #ffd23f 0 14px, transparent 14px 24px); opacity: .6; }
.chapter { position: relative; display: flex; gap: 1rem; }
.chapter-node { position: absolute; left: -2.6rem; top: .4rem; width: 3.4rem; height: 3.4rem; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 1.7rem; background: radial-gradient(circle, var(--ch-color), #1d0838); border: 3px solid #ffd23f; box-shadow: 0 0 20px var(--ch-color); z-index: 2; }
.node-num { position: absolute; bottom: -6px; right: -6px; background: #ffd23f; color: #1a0933; font-weight: 900; font-size: .7rem; border-radius: 99px; padding: 0 .35rem; }
.chapter-body { flex: 1; margin-left: 1.4rem; background: linear-gradient(160deg, color-mix(in srgb, var(--ch-color) 30%, #1d0838), #12052a); border-radius: 1.2rem; padding: 1rem; border: 1px solid color-mix(in srgb, var(--ch-color) 60%, transparent); }
.chapter.locked .chapter-body { filter: grayscale(.9); opacity: .55; }
.chapter.locked .chapter-node { filter: grayscale(1); }
.chapter.claimed .chapter-body { box-shadow: 0 0 24px rgba(31, 209, 139, .3); }
.chapter-head { display: flex; justify-content: space-between; align-items: center; gap: .6rem; flex-wrap: wrap; }
.chapter-head h4 { margin: 0; font-size: 1.1rem; }
.chapter-sub { font-size: .78rem; color: var(--fc-muted); }
.chapter-actions { display: flex; gap: .5rem; align-items: center; flex-wrap: wrap; }
.monsters { display: grid; grid-template-columns: repeat(5, 1fr); gap: .6rem; margin-top: .8rem; }
.monster { background: rgba(0,0,0,.3); border-radius: .9rem; padding: .6rem .5rem; text-align: center; border: 1px solid rgba(255,255,255,.08); }
.monster.captured { border-color: var(--fc-gold); background: rgba(255, 204, 0, .1); }
.mon-glyph { font-size: 2rem; filter: grayscale(1) brightness(.5); }
.monster.captured .mon-glyph { filter: none; animation: floaty 3s ease-in-out infinite; will-change: transform; }
.mon-name { font-weight: 800; font-size: .8rem; }
.mon-task { font-size: .68rem; color: var(--fc-muted); min-height: 2.4em; margin-bottom: .3rem; }

.vip-hero { display: grid; grid-template-columns: auto 1fr auto; gap: 1.2rem; align-items: center; border-radius: 1.4rem; padding: 1.2rem 1.4rem; background: radial-gradient(circle at 0% 50%, color-mix(in srgb, var(--tier) 40%, transparent), transparent 60%), var(--fc-panel-2); border: 2px solid var(--tier); box-shadow: 0 0 30px color-mix(in srgb, var(--tier) 40%, transparent); margin-bottom: 1rem; }
.vip-badge { font-size: 3.6rem; }
.vip-tier { font-family: var(--display); font-size: 1.8rem; color: var(--tier); }
.vip-points { color: #eadcff; margin-bottom: .4rem; }
.vip-bar { height: 18px; max-width: 520px; }
.rewards-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }
.rw-card { background: var(--fc-panel); border-radius: 1.2rem; padding: 1rem 1.2rem; border: 1px solid rgba(255,255,255,.1); margin-bottom: 1rem; }
.rw-card h4 { font-size: 1rem; color: #ffe8a3; }
.family-row { display: grid; grid-template-columns: 150px 1fr; align-items: center; gap: .6rem; margin-bottom: .45rem; font-size: .85rem; }
.tier-table { width: 100%; font-size: .85rem; }
.tier-table th { color: var(--fc-muted); font-size: .7rem; letter-spacing: 1px; text-transform: uppercase; }
.tier-table td, .tier-table th { padding: .35rem .4rem; border-bottom: 1px solid rgba(255,255,255,.07); }
.tier-table tr.current td { color: #1a0933; background: var(--gold-grad); font-weight: 800; }
.tier-table tr.passed td { color: var(--fc-green); }
.profile-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: .7rem; }
.pf-stat { background: rgba(0,0,0,.3); border-radius: .9rem; padding: .6rem; text-align: center; display: flex; flex-direction: column; }
.pf-stat span { font-size: .68rem; color: var(--fc-muted); text-transform: uppercase; letter-spacing: 1px; }
.pf-stat strong { font-family: var(--display); font-weight: 400; font-size: 1.2rem; color: var(--fc-gold); }
.pf-stat em { font-size: .68rem; color: #dccbff; }
.pf-feed { grid-column: 1 / 5; font-size: .8rem; }
.pf-feed ul { margin: .3rem 0 0; padding-left: 1rem; color: #dccbff; }
.pf-reset { grid-column: 5 / 7; display: flex; align-items: flex-end; justify-content: flex-end; gap: .8rem; flex-wrap: wrap; }
.pf-id { font-size: .7rem; color: var(--fc-muted); text-align: right; }
.pf-id code { color: var(--fc-cyan); }
.leaderboard .lb-table td:first-child { width: 2.5rem; color: var(--fc-gold); font-weight: 800; }
.leaderboard .lb-table tr.current td:first-child { color: #1a0933; }

.dash-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }
.dash-col { background: var(--fc-panel); border-radius: 1.3rem; padding: 1rem; border: 1px solid rgba(255,255,255,.1); display: flex; flex-direction: column; gap: .7rem; }
.dash-col.week { border-color: rgba(0, 194, 255, .4); } .dash-col.month { border-color: rgba(255, 204, 0, .45); }
.dash-head { display: flex; justify-content: space-between; align-items: baseline; font-family: var(--display); color: #ffe8a3; }
.dash-reset { font-family: 'Poppins', sans-serif; font-size: .72rem; color: var(--fc-muted); }
.mission { background: rgba(0,0,0,.3); border-radius: .9rem; padding: .7rem; border: 1px solid rgba(255,255,255,.08); }
.mission.done { border-color: var(--fc-green); }
.mission.claimed { opacity: .6; }
.mission-text { font-weight: 700; font-size: .86rem; margin-bottom: .4rem; }
.mission-foot { display: flex; justify-content: space-between; align-items: center; margin-top: .45rem; }
.mission-reward { color: var(--fc-gold); font-weight: 800; font-size: .82rem; }
.dash-chest { display: flex; align-items: center; gap: .6rem; border-radius: .9rem; padding: .6rem .8rem; background: linear-gradient(90deg, rgba(255,204,0,.12), transparent); border: 1px dashed rgba(255,204,0,.45); }
.dash-chest.ready { border-style: solid; box-shadow: 0 0 20px rgba(255, 204, 0, .4); }
.chest-icon { font-size: 1.8rem; }
.chest-text { flex: 1; font-size: .8rem; font-weight: 700; }

/* ------------------------------------------------------- toasts & overlays */
#fc-toasts { position: fixed; top: 76px; right: 16px; z-index: 2000; display: flex; flex-direction: column; gap: .5rem; width: min(360px, 92vw); pointer-events: none; }
.fc-toast { pointer-events: auto; display: flex; gap: .7rem; align-items: center; padding: .7rem .9rem; border-radius: 1rem; background: rgba(29, 8, 56, .96); border: 1px solid rgba(255,255,255,.14); border-left: 5px solid var(--fc-cyan); box-shadow: 0 14px 30px rgba(0,0,0,.55); animation: toastIn .35s cubic-bezier(.3, 1.4, .5, 1); cursor: pointer; }
.fc-toast.success { border-left-color: var(--fc-green); } .fc-toast.warning { border-left-color: var(--fc-gold); }
.fc-toast.pack { border-left-color: var(--fc-pink); } .fc-toast.monster { border-left-color: #b06bff; }
.fc-toast.out { animation: toastOut .4s ease forwards; }
.ht-icon { font-size: 1.6rem; }
.ht-title { font-weight: 800; font-size: .9rem; }
.ht-text { font-size: .8rem; color: #dccbff; }
@keyframes toastIn { from { transform: translateX(120%); opacity: 0; } to { transform: none; opacity: 1; } }
@keyframes toastOut { to { transform: translateX(120%); opacity: 0; } }

#fc-celebrate { position: fixed; inset: 0; z-index: 3000; display: none; align-items: center; justify-content: center; background: radial-gradient(circle, rgba(40, 6, 70, .75), rgba(0,0,0,.88)); cursor: pointer; overflow: hidden; }
#fc-celebrate.show { display: flex; animation: fadeIn .25s ease; }
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
.celebrate-inner { text-align: center; position: relative; animation: bannerIn .5s cubic-bezier(.3, 1.6, .5, 1); }
.cb-burst { will-change: transform; position: absolute; top: 50%; left: 50%; width: 900px; height: 900px; margin: -450px 0 0 -450px; background: repeating-conic-gradient(rgba(255, 204, 0, .16) 0 10deg, transparent 10deg 20deg); border-radius: 50%; animation: spinBurst 12s linear infinite; z-index: -1; mask-image: radial-gradient(circle, #000 20%, transparent 65%); }
@keyframes spinBurst { to { transform: rotate(360deg); } }
.cb-icon { font-size: 5rem; animation: floaty 2s ease-in-out infinite; will-change: transform; }
.cb-title { font-family: var(--display); font-size: clamp(2.6rem, 8vw, 5.5rem); background: var(--gold-grad); -webkit-background-clip: text; background-clip: text; color: transparent; filter: drop-shadow(0 6px 0 #7a3b00) drop-shadow(0 0 30px rgba(255, 170, 0, .6)); line-height: 1.05; }
.celebrate-inner.mega .cb-title, .celebrate-inner.epic .cb-title { background: linear-gradient(180deg, #fff, #ff9ad5 40%, #ff2e88); -webkit-background-clip: text; background-clip: text; filter: drop-shadow(0 6px 0 #6a0040) drop-shadow(0 0 36px rgba(255, 46, 136, .8)); }
.celebrate-inner.level .cb-title, .celebrate-inner.vip .cb-title { background: linear-gradient(180deg, #fff, #9ef7ff 40%, #00c2ff); -webkit-background-clip: text; background-clip: text; filter: drop-shadow(0 6px 0 #00445a) drop-shadow(0 0 30px rgba(0, 194, 255, .7)); }
.cb-amount { font-family: var(--display); font-size: clamp(2rem, 6vw, 4rem); color: #fff; text-shadow: 0 4px 0 rgba(0,0,0,.5); font-variant-numeric: tabular-nums; }
.cb-sub { color: #f6e6ff; font-weight: 700; margin-top: .3rem; }
.cb-tap { margin-top: 1.2rem; font-size: .7rem; letter-spacing: 3px; color: rgba(255,255,255,.5); text-transform: uppercase; }
.coin-drop { position: fixed; top: -60px; font-size: 2.2rem; animation-name: coinFall; animation-timing-function: linear; animation-iteration-count: infinite; pointer-events: none; }
@keyframes coinFall { 0% { transform: translateY(0) rotate(0); } 100% { transform: translateY(115vh) rotate(540deg); } }

/* ------------------------------------------------------- multi-hand video poker */
.vp-hands-btns { display: flex; gap: .3rem; justify-content: center; }
.vp-hands-btn { min-width: 2.3rem; height: 2.3rem; border-radius: 50%; border: 2px solid rgba(255, 210, 63, .55); background: #071a45; color: #ffd23f; font-weight: 900; font-size: .85rem; cursor: pointer; transition: transform .1s, background .15s; }
.vp-hands-btn:hover { transform: translateY(-2px); border-color: #ffd23f; }
.vp-hands-btn.selected { background: var(--gold-grad); color: #2a1300; border-color: #fff3a8; box-shadow: 0 0 14px rgba(255, 210, 63, .6); }
.vp-hands-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(168px, 1fr)); gap: .35rem .5rem; margin: 0 auto 1.5rem; max-width: 980px; }
.vp-hands-grid.n3 { grid-template-columns: repeat(2, minmax(168px, 230px)); justify-content: center; }
.vp-hands-grid.n5 { grid-template-columns: repeat(4, minmax(168px, 1fr)); }
.vp-hands-grid.n10 { grid-template-columns: repeat(3, minmax(168px, 1fr)); }
.vp-hands-grid.n25 { grid-template-columns: repeat(4, minmax(168px, 1fr)); }
.vp-mini-hand { display: flex; align-items: center; gap: .35rem; background: rgba(0, 10, 58, .7); border: 1px solid rgba(255, 210, 63, .25); border-radius: .5rem; padding: .2rem .35rem; min-height: 2.1rem; transition: background .2s; }
.vp-mini-hand.won { border-color: #ffd23f; background: linear-gradient(90deg, rgba(255, 210, 63, .28), rgba(0, 10, 58, .7)); box-shadow: 0 0 10px rgba(255, 210, 63, .35); }
.vp-mini-hand.lost { opacity: .55; }
.mh-no { font-size: .62rem; color: #8fa4d8; width: 1.1rem; text-align: right; font-weight: 800; }
.mh-cards { display: flex; gap: 2px; }
.mh-res { font-size: .62rem; color: #ffd23f; font-weight: 800; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; flex: 1; text-align: right; }
.mcard { display: inline-flex; align-items: center; justify-content: center; width: 1.55rem; height: 1.85rem; border-radius: 3px; background: #fff; font-size: .68rem; font-weight: 900; letter-spacing: -.5px; line-height: 1; }
.mcard.red { color: #d10f2f; } .mcard.black { color: #14121a; } .mcard.joker { color: #7b2cbf; }
.mcard.back { background: repeating-linear-gradient(45deg, #7b1b8f 0 4px, #5a0f6b 4px 8px); border: 1px solid #fff; }
.mcard.fresh { animation: mcIn .35s ease both; }
@keyframes mcIn { from { transform: rotateY(90deg); } to { transform: none; } }
.vp-double { display: flex; justify-content: center; align-items: flex-end; gap: 2rem; flex-wrap: wrap; }
.vp-dbl-dealer, .vp-dbl-picks { display: flex; flex-direction: column; align-items: center; gap: .5rem; }
.vp-dbl-dealer .pcard { width: 112px; height: 156px; box-shadow: 0 0 0 4px var(--fc-red), 0 10px 24px rgba(255, 77, 109, .35); }
.vp-dbl-dealer .pc-center { font-size: 3.3rem; }
.vp-dbl-slot { cursor: pointer; transition: transform .12s; }
.vp-dbl-slot:hover { transform: translateY(-8px) rotate(-1deg); }
.vp-dbl-slot .pcard { box-shadow: 0 0 0 3px rgba(255, 210, 63, .6); }
.pcard.chosen.win { box-shadow: 0 0 0 4px var(--fc-green), 0 0 28px rgba(31, 209, 139, .7); transform: translateY(-10px); }
.pcard.chosen.lose { box-shadow: 0 0 0 4px var(--fc-red), 0 0 28px rgba(255, 77, 109, .6); transform: translateY(-10px); }
.pcard.chosen.push { box-shadow: 0 0 0 4px var(--fc-cyan), 0 0 28px rgba(0, 194, 255, .6); transform: translateY(-10px); }
.pcard.dim { opacity: .45; filter: grayscale(.4); }
.vp-double-bar { display: flex; justify-content: center; align-items: center; gap: .7rem; margin-top: .7rem; flex-wrap: wrap; animation: fadeUp .3s ease; }
.vp-double-bar .btn-deal.gold { animation: pulseGold 1.4s ease-in-out infinite; }
@keyframes pulseGold { 0%, 100% { box-shadow: 0 5px 0 #a35f00, 0 0 0 rgba(255, 204, 0, 0); } 50% { box-shadow: 0 5px 0 #a35f00, 0 0 26px rgba(255, 204, 0, .75); } }
.vp-dbl-count { color: #8fa4d8; font-size: .8rem; font-weight: 700; }
.vp-lose { color: var(--fc-red); }

/* ------------------------------------------------------------- player name */
.hud-name { cursor: pointer; color: #fff; max-width: 170px; overflow: hidden; text-overflow: ellipsis; border-color: rgba(0, 194, 255, .5) !important; }
.hud-name:hover { border-color: var(--fc-gold) !important; box-shadow: 0 0 12px rgba(255, 204, 0, .35); }
.hud-name-icon { margin-right: .3rem; }
.modal-content:has(.fc-name-modal) { background: radial-gradient(circle at 50% 0%, #4a1d86, #14062a 75%); border: 2px solid rgba(255, 204, 0, .6); border-radius: 1.4rem; color: var(--fc-text); box-shadow: 0 0 60px rgba(123, 44, 191, .55); }
.modal-content:has(.fc-name-modal) .modal-header, .modal-content:has(.fc-name-modal) .modal-footer { border-color: rgba(255, 255, 255, .1); }
.modal-content:has(.fc-name-modal) .modal-title { font-family: var(--display); font-size: 1.25rem; background: var(--gold-grad); -webkit-background-clip: text; background-clip: text; color: transparent; }
.fc-name-modal p { color: #e6d8ff; }
.fc-name-modal .fc-name-hint { color: var(--fc-cyan); font-size: .88rem; }
.fc-name-modal .form-control { background: rgba(10, 2, 24, .7); border: 2px solid rgba(255, 204, 0, .5); color: #fff; font-size: 1.15rem; font-weight: 700; border-radius: .8rem; padding: .6rem .9rem; }
.fc-name-modal .form-control:focus { border-color: var(--fc-gold); box-shadow: 0 0 0 .2rem rgba(255, 204, 0, .25); }
.fc-name-modal .control-label { color: var(--fc-muted); font-size: .75rem; letter-spacing: 1px; text-transform: uppercase; }
.fc-name-rules { color: var(--fc-muted); font-size: .75rem; margin-top: .3rem; }
.fc-name-error { margin-top: .6rem; color: #fff; background: rgba(255, 77, 109, .25); border: 1px solid var(--fc-red); border-radius: .6rem; padding: .4rem .7rem; font-size: .85rem; animation: shake .35s ease; }
@keyframes shake { 25% { transform: translateX(-5px); } 75% { transform: translateX(5px); } }

/* ---------------------------------------------------------------- My Stats */
.stats-page .pos { color: var(--fc-green); } .stats-page .neg { color: var(--fc-red); } .stats-page .flat { color: var(--fc-muted); }
.stats-page .muted, .community .muted { color: var(--fc-muted); font-size: .82rem; }
.kpi-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(155px, 1fr)); gap: .7rem; margin-bottom: 1rem; }
.kpi { background: var(--fc-panel); border: 1px solid rgba(255, 255, 255, .1); border-radius: 1rem; padding: .7rem .85rem; }
.kpi.gold { border-color: rgba(255, 204, 0, .55); box-shadow: 0 0 20px rgba(255, 204, 0, .12); }
.kpi-label { color: var(--fc-muted); font-size: .68rem; letter-spacing: .6px; text-transform: uppercase; font-weight: 700; min-height: 2.1em; }
.kpi-icon { margin-right: .3rem; }
.kpi-value { font-family: var(--display); font-size: 1.35rem; margin: .15rem 0; font-variant-numeric: tabular-nums; white-space: nowrap; }
.kpi.gold .kpi-value { background: var(--gold-grad); -webkit-background-clip: text; background-clip: text; color: transparent; }
.kpi-sub { color: #cdb9ef; font-size: .74rem; }
.stats-card-head { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: .5rem; }
.stats-legend { display: flex; gap: .9rem; font-size: .75rem; color: var(--fc-muted); }
.stats-legend .lg::before { content: ""; display: inline-block; width: 14px; height: 4px; border-radius: 2px; margin-right: .35rem; vertical-align: middle; }
.lg-bal::before { background: var(--fc-green); } .lg-peak::before { background: var(--fc-gold); } .lg-dd::before { background: rgba(255, 77, 109, .55); height: 10px !important; }
.stats-chart-wrap { position: relative; }
.stats-chart { width: 100%; height: auto; display: block; }
.stats-chart .sc-grid { stroke: rgba(255, 255, 255, .07); stroke-width: 1; }
.stats-chart .sc-axis { fill: #9c88c4; font-size: 11px; font-family: Poppins, sans-serif; }
.stats-chart .sc-fill { fill: url(#fcBalFill); }
.stats-chart .sc-dd { fill: rgba(255, 77, 109, .28); }
.stats-chart .sc-peak { fill: none; stroke: var(--fc-gold); stroke-width: 1.3; stroke-dasharray: 5 4; opacity: .85; }
.stats-chart .sc-line { fill: none; stroke-width: 2.4; stroke-linejoin: round; stroke-dasharray: 4000; stroke-dashoffset: 4000; animation: drawLine 1.2s ease forwards; }
.stats-chart .sc-line.up { stroke: var(--fc-green); filter: drop-shadow(0 0 4px rgba(31, 209, 139, .6)); }
.stats-chart .sc-line.down { stroke: var(--fc-red); filter: drop-shadow(0 0 4px rgba(255, 77, 109, .6)); }
@keyframes drawLine { to { stroke-dashoffset: 0; } }
.stats-chart .sc-dot { stroke: #fff; stroke-width: 2; } .stats-chart .sc-dot.up { fill: var(--fc-green); } .stats-chart .sc-dot.down { fill: var(--fc-red); }
.stats-chart .sc-ddmark { stroke: var(--fc-red); stroke-width: 1.5; stroke-dasharray: 3 3; }
.stats-chart .sc-ddtext { fill: #ff9fb0; font-size: 11px; font-weight: 700; font-family: Poppins, sans-serif; }
.stats-chart-note { color: var(--fc-muted); font-size: .72rem; margin-top: .3rem; }
.stats-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }
.stats-empty { color: var(--fc-muted); font-size: .88rem; padding: .6rem 0; }
.stats-empty .fc-progress { margin-top: .6rem; }
.stats-table { width: 100%; font-size: .84rem; }
.stats-table th { color: var(--fc-muted); font-size: .68rem; letter-spacing: 1px; text-transform: uppercase; font-weight: 700; }
.stats-table td, .stats-table th { padding: .34rem .4rem; border-bottom: 1px solid rgba(255, 255, 255, .07); }
.stats-table td:last-child { text-align: right; font-weight: 700; }
.stats-table th:last-child { text-align: right; }
.stats-table tr.current td { background: rgba(255, 204, 0, .1); }
.you-tag { margin-left: .4rem; font-size: .6rem; font-weight: 900; background: var(--pink-grad); color: #fff; border-radius: 99px; padding: .05rem .45rem; vertical-align: middle; text-transform: uppercase; letter-spacing: .5px; }
.tend-hero { display: flex; align-items: center; gap: .8rem; margin-bottom: .6rem; }
.tend-arrow { font-size: 2.3rem; line-height: 1; }
.tend-label { font-family: var(--display); font-size: 1.3rem; }
.tend-hero.rising .tend-label { color: var(--fc-green); } .tend-hero.falling .tend-label { color: var(--fc-red); } .tend-hero.steady .tend-label { color: var(--fc-cyan); }
.tend-sub { color: var(--fc-muted); font-size: .78rem; }
.cat-hero { margin-bottom: .8rem; }
.cat-fav { font-family: var(--display); font-size: 1.25rem; background: var(--gold-grad); -webkit-background-clip: text; background-clip: text; color: transparent; }
.cat-tags { display: flex; gap: .35rem; flex-wrap: wrap; margin-top: .3rem; }
.cat-tag { font-size: .72rem; font-weight: 700; border: 1px solid rgba(255, 255, 255, .2); border-radius: 99px; padding: .1rem .55rem; color: #e6d8ff; }
.cat-tag.gold { border-color: var(--fc-gold); color: var(--fc-gold); }
.category .family-row { grid-template-columns: 170px 1fr; }
.arch-hero { display: flex; gap: .9rem; align-items: center; margin-bottom: .7rem; }
.arch-icon { font-size: 3rem; line-height: 1; filter: drop-shadow(0 0 12px rgba(255, 204, 0, .45)); animation: popIn .5s ease; }
@keyframes popIn { from { transform: scale(.4); opacity: 0; } 70% { transform: scale(1.12); } to { transform: none; opacity: 1; } }
.arch-name { font-family: var(--display); font-size: 1.35rem; color: #ffe8a3; }
.arch-conf { color: var(--fc-cyan); font-size: .75rem; font-weight: 700; }
.arch-desc { color: #e6d8ff; font-size: .85rem; margin-top: .15rem; }
.feat-table td:nth-child(2) { text-align: right; font-weight: 800; }
.arch-votes { display: flex; gap: .35rem; flex-wrap: wrap; margin-top: .6rem; }
.vote { font-size: .72rem; border-radius: 99px; padding: .1rem .55rem; background: rgba(255, 255, 255, .08); }
.vote.top { background: var(--gold-grad); color: #2a1300; font-weight: 800; }

/* ------------------------------------------------------------- responsive */
@media (max-width: 1400px) {
  .navbar .nav-link { font-size: .72rem; padding: .35rem .45rem !important; }
  .hud-vip, .hud-stars { display: none; }
}
@media (max-width: 1100px) {
  .vp-controls { grid-template-columns: 1fr 1fr 1fr; }
  .vp-hands-grid.n25, .vp-hands-grid.n5 { grid-template-columns: repeat(3, minmax(150px, 1fr)); }
  .cat-row { grid-template-columns: repeat(3, 1fr); }
  .rl-layout { grid-template-columns: 1fr; }
  .profile-grid { grid-template-columns: repeat(3, 1fr); }
  .pf-feed, .pf-reset { grid-column: 1 / -1; }
}
@media (max-width: 800px) {
  .sm-controls { grid-template-columns: 1fr; }
  .btn-spin { margin-top: 0; }
  .monsters { grid-template-columns: repeat(2, 1fr); }
  .dash-grid, .rewards-grid { grid-template-columns: 1fr; }
  .vp-controls { grid-template-columns: 1fr 1fr; }
  .stats-grid { grid-template-columns: 1fr; }
  .vp-hands-grid, .vp-hands-grid.n3, .vp-hands-grid.n5, .vp-hands-grid.n10, .vp-hands-grid.n25 { grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); }
  .jb-pots { grid-template-columns: repeat(2, 1fr); }
  .hero { flex-direction: column; text-align: center; }
