    if (!file.exists(descpath))
      return("unknown")

    desc <- tryCatch(
      read.dcf(descpath, all = TRUE),
      error = identity
    )

    if (inherits(desc, "error"))
      return("unknown")

    type <- desc$Type
    if (!is.null(type))
      return(tolower(type))

    package <- desc$Package
    if (!is.null(package))
      return("package")

